/*
  STANDALONE DARK THEME
  Defines all CSS variables Claude normally provides so this file
  looks identical whether opened inside Claude or in any browser.
*/
:root {
  --color-background-primary:   #151515;
  --color-background-secondary: #202020;
  --color-background-info:      #16252B;
  --color-text-primary:   #EEEDF0;
  --color-text-secondary: #8B8A94;
  --color-text-info:      #00AFEF;
  --color-border-secondary: #3D3C4A;
  --color-border-tertiary:  #2A2936;
  --border-radius-sm:   4px;
  --border-radius-md:   8px;
  --border-radius-lg:   12px;
  --border-radius-xl:   16px;
  --border-radius-full: 9999px;
}
html, body {
  background: #080808 !important;
  color: #EEEDF0 !important;
  margin: 0; padding: 0;
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 13px;
}
select, input, textarea { color-scheme: dark; }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--color-background-secondary); }
::-webkit-scrollbar-thumb { background: var(--color-border-secondary); border-radius: 3px; }


/* ===== Original style block 002: inline-style-002 ===== */

*{box-sizing:border-box;margin:0;padding:0;}
.wrap{padding:.75rem 1rem;}
.top-bar{display:flex;align-items:center;justify-content:space-between;margin-bottom:1.25rem;flex-wrap:wrap;gap:8px;}
