.view-link{font-size:11px;padding:4px 10px;border:0.5px solid #FA873D;border-radius:var(--border-radius-md);background:#FFF0E6;color:#8A3E0D;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:4px;white-space:nowrap;font-family:inherit;}
.view-link:hover{background:#FA873D;color:#fff;}
.report-result{background:#E1F5EE;border:0.5px solid #1D9E75;border-radius:var(--border-radius-md);padding:10px 14px;margin-top:9px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;}
.report-result .rr-name{font-size:12px;font-weight:500;color:var(--color-text-primary);}
.report-result .rr-ts{font-size:11px;color:var(--color-text-secondary);}
.pace-rep-row{display:grid;grid-template-columns:110px 1fr 1fr 1fr 1fr 80px;gap:6px;padding:8px 0;border-bottom:0.5px solid var(--color-border-tertiary);align-items:center;font-size:12px;}
.pace-rep-row:last-child{border-bottom:none;}
.pace-hdr{display:grid;grid-template-columns:110px 1fr 1fr 1fr 1fr 80px;gap:6px;padding:5px 0 8px;border-bottom:0.5px solid var(--color-border-secondary);font-size:11px;font-weight:500;color:var(--color-text-secondary);}
.pace-cell{display:flex;flex-direction:column;gap:2px;}
.pace-val{font-size:11px;font-weight:500;}
.pace-bar-wrap{height:4px;background:var(--color-border-tertiary);border-radius:3px;overflow:hidden;margin-top:2px;}
.pace-bar-fill{height:100%;border-radius:3px;}
.pace-green{color:#5DCAA5;}.pace-amber{color:#EF9F27;}.pace-red{color:#F09595;}
.pace-dot-green{background:#5DCAA5;width:8px;height:8px;border-radius:50%;display:inline-block;}
.pace-dot-amber{background:#EF9F27;width:8px;height:8px;border-radius:50%;display:inline-block;}
.pace-dot-red{background:#F09595;width:8px;height:8px;border-radius:50%;display:inline-block;}
.pace-alert{display:flex;align-items:flex-start;gap:8px;padding:8px 10px;border-radius:var(--border-radius-md);margin-bottom:6px;font-size:12px;}
.pace-alert-red{background:#2A1A1A;border:0.5px solid #F09595;color:#F09595;}
.pace-alert-amber{background:#251F10;border:0.5px solid #EF9F27;color:#EF9F27;}



/* ========== V238 DASHBOARD COMMAND CENTER ========== */
.dash-command-page{position:relative;}
.dash-hero{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:4px 0 18px;padding:22px 24px;border:1px solid rgba(250,135,61,.28);border-radius:24px;background:radial-gradient(circle at 12% 10%,rgba(250,135,61,.34),transparent 34%),radial-gradient(circle at 88% 20%,rgba(29,158,117,.16),transparent 30%),linear-gradient(135deg,rgba(16,23,45,.96),rgba(11,16,31,.90));box-shadow:0 18px 54px rgba(0,0,0,.34),inset 0 1px 0 rgba(255,255,255,.08);overflow:hidden;}
.dash-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.18em;color:#00AFEF;font-weight:800;margin-bottom:7px;}
.dash-hero h1{font-size:28px;line-height:1.05;color:#fff;margin:0 0 7px;font-weight:850;letter-spacing:-.035em;}
.dash-hero p{font-size:13px;color:#AEB8D6;line-height:1.5;max-width:680px;margin:0;}
.dash-hero-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;justify-content:flex-end;}
.dash-action-btn{border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);color:#DDE7FF;border-radius:14px;padding:10px 13px;font-size:12px;font-weight:750;cursor:pointer;box-shadow:inset 0 1px 0 rgba(255,255,255,.06);transition:transform .15s ease,background .15s ease,border-color .15s ease;}
.dash-action-btn:hover{transform:translateY(-1px);background:rgba(250,135,61,.18);border-color:rgba(250,135,61,.55);}
.dash-action-btn.primary{background:linear-gradient(135deg,#FA873D,#00AFEF);color:#fff;border-color:rgba(255,255,255,.15);box-shadow:0 10px 30px rgba(90,91,255,.32);}
.dash-alert-zone{margin-bottom:12px;}
.dash-command-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:14px;align-items:start;}
.dash-layout-toolbar{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;padding:2px 2px 0;color:#7E89AA;font-size:11px;}
.dash-save-layout{font-size:11px;padding:5px 11px;border:1px solid rgba(250,135,61,.45);border-radius:12px;background:rgba(250,135,61,.12);color:#BFC7FF;cursor:pointer;font-weight:700;}
.dash-widget-shell{position:relative;min-width:0;}
.dash-widget-shell .card,.dash-widget-shell .mc{box-shadow:0 14px 38px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.055);}
.dash-widget-shell .card{border:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(18,28,54,.92),rgba(12,18,35,.94));border-radius:20px;padding:16px 18px;overflow:hidden;}
.dash-widget-shell .ct{font-size:14px;font-weight:800;color:#EEF4FF;letter-spacing:-.01em;margin-bottom:13px;}
.dash-kpi-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:2px;}
.dash-kpi{position:relative;border-radius:20px;padding:16px 17px;min-height:132px;overflow:hidden;border:1px solid rgba(255,255,255,.10);background:linear-gradient(145deg,rgba(35,48,86,.88),rgba(12,18,35,.95));box-shadow:0 18px 45px rgba(0,0,0,.30),inset 0 1px 0 rgba(255,255,255,.07);}
.dash-kpi:before{content:"";position:absolute;inset:-1px;background:radial-gradient(circle at 22% 15%,var(--kpi-glow,rgba(250,135,61,.34)),transparent 42%);opacity:.95;pointer-events:none;}
.dash-kpi .kpi-icon{position:relative;width:38px;height:38px;border-radius:15px;display:flex;align-items:center;justify-content:center;margin-bottom:11px;background:linear-gradient(135deg,var(--kpi-color,#FA873D),rgba(255,255,255,.10));box-shadow:0 10px 28px var(--kpi-shadow,rgba(250,135,61,.25));font-size:18px;}
.dash-kpi .lbl{position:relative;font-size:11px;color:#B8C4E2;font-weight:750;text-transform:uppercase;letter-spacing:.07em;margin-bottom:5px;}
.dash-kpi .val{position:relative;font-size:23px;line-height:1.1;color:#fff;font-weight:900;letter-spacing:-.03em;}
.dash-kpi .sub{position:relative;font-size:11px;color:#8D98B8;margin-top:7px;line-height:1.35;}
.dash-kpi .mini-bar{position:relative;height:7px;border-radius:999px;background:rgba(255,255,255,.08);margin-top:13px;overflow:hidden;}
.dash-kpi .mini-bar span{display:block;height:100%;width:var(--pct,0%);background:linear-gradient(90deg,var(--kpi-color,#FA873D),rgba(255,255,255,.55));border-radius:999px;}
.dash-widget-shell[data-size="full"]{grid-column:span 12;}
.dash-widget-shell[data-size="half"]{grid-column:span 6;}
.dash-widget-shell[data-size="third"]{grid-column:span 4;}
.dash-widget-shell[data-size="twoThird"]{grid-column:span 8;}
#dashWidgetContainer canvas{filter:drop-shadow(0 10px 20px rgba(0,0,0,.20));}
@media(max-width:1180px){.dash-kpi-grid{grid-template-columns:repeat(3,1fr)}.dash-widget-shell[data-size="half"],.dash-widget-shell[data-size="third"],.dash-widget-shell[data-size="twoThird"]{grid-column:span 12;}}
@media(max-width:720px){.dash-hero{align-items:flex-start;flex-direction:column;padding:18px}.dash-hero h1{font-size:24px}.dash-hero-actions{justify-content:flex-start}.dash-kpi-grid{grid-template-columns:1fr}.dash-command-grid{grid-template-columns:1fr}.dash-widget-shell,.dash-widget-shell[data-size="full"],.dash-widget-shell[data-size="half"],.dash-widget-shell[data-size="third"],.dash-widget-shell[data-size="twoThird"]{grid-column:1/-1!important;}}

/* ========== INTEL SOURCE CITATIONS ========== */
.intel-source { font-size:10px; color:#8B8A94; font-style:italic; margin-top:6px; padding-top:5px; border-top:0.5px dashed rgba(250,135,61,.25); }
.intel-source::before { content:"\1F4DA  Source: "; font-weight:600; color:#FA873D; font-style:normal; }
body.hide-intel-sources .intel-source { display:none !important; }
body.hide-intel-sources #intelSourcesSection { display:none !important; }
#intelSourcesSection { background:var(--color-background-secondary); border:0.5px solid var(--color-border-secondary); border-radius:var(--border-radius-md); padding:14px 16px; margin-top:18px; }
#intelSourcesSection h4 { font-size:12px; font-weight:600; color:#8EDCFA; text-transform:uppercase; letter-spacing:.05em; margin-bottom:10px; }
#intelSourcesSection .src-row { font-size:11px; color:var(--color-text-primary); padding:6px 0; border-bottom:0.5px solid var(--color-border-tertiary); }
#intelSourcesSection .src-row:last-child { border-bottom:none; }
#intelSourcesSection .src-row .src-claim { color:var(--color-text-secondary); font-size:10.5px; margin-top:2px; }
#intelSourcesSection .src-disclaimer { font-size:10.5px; color:#EF9F27; background:rgba(239,159,39,.08); border-left:2px solid #EF9F27; padding:8px 11px; border-radius:0 6px 6px 0; margin-top:10px; line-height:1.5; }
@media print { body.hide-intel-sources .intel-source, body.hide-intel-sources #intelSourcesSection { display:none !important; } }


/* ===== Original style block 003: tcp-command-center-ui-v237 ===== */

/* ========== TCP SALES OPS COMMAND CENTER UI v237 ========== */
:root{
  --tcp-bg-0:#050505;
  --tcp-bg-1:#0B0B0B;
  --tcp-bg-2:#121212;
  --tcp-sidebar:#0B0B0B;
  --tcp-panel:#151515;
  --tcp-panel-2:#202020;
  --tcp-line:rgba(255,255,255,.07);
  --tcp-line-strong:rgba(255,255,255,.16);
  --tcp-text:#F2F3F7;
  --tcp-muted:#9AA0B3;
  --tcp-purple:#FA873D;
  --tcp-violet:#FA873D;
  --tcp-cyan:#00AFEF;
  --tcp-orange:#FA873D;
  --tcp-gold:#FBBF24;
  --tcp-green:#34D399;
  --tcp-red:#FB7185;
  --tcp-blue:#00AFEF;
  --color-background-primary:var(--tcp-panel);
  --color-background-secondary:var(--tcp-panel-2);
  --color-background-info:#101C20;
  --color-border-tertiary:var(--tcp-line);
  --color-border-secondary:rgba(255,255,255,.14);
  --color-text-primary:var(--tcp-text);
  --color-text-secondary:var(--tcp-muted);
  --color-text-info:#8EDCFA;
  --border-radius-md:10px;
  --border-radius-lg:14px;
  --tcp-accent:var(--tcp-violet);
  --tcp-shadow:0 8px 28px rgba(0,0,0,.38);
  --tcp-shadow-soft:0 2px 10px rgba(0,0,0,.24);
}
html{background:var(--tcp-bg-0)!important;}
body{
  min-height:100vh;
  background:
    radial-gradient(circle at 15% 3%,rgba(250,135,61,.26) 0,transparent 26rem),
    radial-gradient(circle at 88% 0%,rgba(0,175,239,.16) 0,transparent 32rem),
    radial-gradient(circle at 80% 85%,rgba(250,135,61,.09) 0,transparent 28rem),
    linear-gradient(135deg,var(--tcp-bg-0) 0%,var(--tcp-bg-1) 42%,#090B14 100%)!important;
  color:var(--tcp-text)!important;
  letter-spacing:.005em;
}
.wrap{max-width:none!important;margin:0!important;padding:18px 22px 34px 274px!important;}
/* Fixed left app navigation */
.tabs{
  position:fixed!important;left:0;top:0;bottom:0;z-index:1000;
  width:248px!important;display:flex!important;flex-direction:column!important;gap:5px!important;
  margin:0!important;padding:22px 14px 18px!important;overflow-y:auto!important;overflow-x:hidden!important;
  border:0!important;border-right:1px solid rgba(255,255,255,.09)!important;
  background:
    linear-gradient(180deg,rgba(16,20,35,.98),rgba(9,12,22,.98)),
    radial-gradient(circle at 10% 0%,rgba(250,135,61,.25),transparent 18rem)!important;
  box-shadow:18px 0 45px rgba(0,0,0,.32),inset -1px 0 0 rgba(255,255,255,.03);
  backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);
  scrollbar-width:thin;
}
.tabs:before{
  content:"▲ SALES TRACKER\A 2026–2030";
  white-space:pre;display:block;margin:0 4px 22px;padding:10px 0 18px 52px;
  min-height:48px;border-bottom:1px solid rgba(255,255,255,.09);
  font-size:12px;line-height:1.35;font-weight:800;letter-spacing:.04em;color:#fff;
  background:
    linear-gradient(135deg,var(--tcp-orange),var(--tcp-purple) 55%,var(--tcp-cyan)) 0 6px/38px 38px no-repeat;
  border-radius:0;
  filter:drop-shadow(0 0 18px rgba(250,135,61,.32));
}
.tabs:after{
  content:"Cloud Sync • Admin";
  margin-top:auto;padding:14px 12px 6px;color:#6F778E;font-size:10px;text-transform:uppercase;letter-spacing:.1em;border-top:1px solid rgba(255,255,255,.08);
}
.tab{
  width:100%;display:flex!important;align-items:center!important;justify-content:flex-start!important;gap:10px!important;
  border:1px solid transparent!important;border-radius:12px!important;background:transparent!important;
  color:#D4D8E8!important;padding:10px 13px!important;text-align:left!important;font-size:13px!important;font-weight:600!important;
  white-space:nowrap;transition:all .16s ease!important;box-shadow:none!important;
}
.tab:hover:not(.active){background:rgba(255,255,255,.055)!important;border-color:rgba(255,255,255,.08)!important;color:#fff!important;transform:translateX(2px);}
.tab.active{
  background:linear-gradient(90deg,var(--tcp-orange),#FA873D 38%,var(--tcp-violet))!important;
  color:#fff!important;border-color:rgba(255,255,255,.18)!important;
  box-shadow:0 12px 26px rgba(250,135,61,.28),inset 0 1px 0 rgba(255,255,255,.22)!important;
}
#tabBar .tab[style]{margin-left:0!important;margin-top:8px!important;border-color:rgba(250,135,61,.28)!important;color:#CFCBFF!important;}
/* Top command bar */
.top-bar{
  position:sticky;top:0;z-index:800;min-height:74px;
  margin:-18px -22px 18px!important;padding:18px 24px!important;
  background:linear-gradient(180deg,rgba(10,13,24,.92),rgba(10,13,24,.70))!important;
  border-bottom:1px solid rgba(255,255,255,.08)!important;
  backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);
  box-shadow:0 18px 40px rgba(0,0,0,.25);
}
.top-bar > div:first-child{display:flex!important;align-items:center!important;gap:10px!important;flex-wrap:wrap;}
.top-bar > div:first-child span:first-child{
  font-size:22px!important;font-weight:900!important;letter-spacing:-.03em!important;color:#fff!important;
  background:linear-gradient(90deg,#fff,#F1F1F1 55%,#8EDCFA);-webkit-background-clip:text;background-clip:text;color:transparent!important;
}
.top-bar > div:first-child:after{
  content:"Sales Operations Command Center";display:block;width:100%;font-size:10px;line-height:1;color:#7E879D;text-transform:uppercase;letter-spacing:.16em;margin-left:2px;margin-top:-2px;
}
.nav-row{gap:8px!important;align-items:center!important;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:8px 10px;box-shadow:inset 0 1px 0 rgba(255,255,255,.05);}
.nav-lbl{font-size:10px!important;text-transform:uppercase;letter-spacing:.09em;color:#7D859A!important;font-weight:800;}
.nav-sel,.wr,.qbadge{
  border-radius:10px!important;border:1px solid rgba(255,255,255,.12)!important;background:rgba(10,13,24,.72)!important;color:#FFFFFF!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.05)!important;
}
.qbadge{background:linear-gradient(135deg,rgba(250,135,61,.25),rgba(250,135,61,.24))!important;color:#FFE7DF!important;}
.wr{color:#8EDCFA!important;}
/* Cards and widgets */
.page{animation:tcpFade .22s ease;}
@keyframes tcpFade{from{opacity:.45;transform:translateY(4px)}to{opacity:1;transform:none}}
.card,.mc,.profile-stat,.chip,.rv-section,.report-card,.note-card,.rep-card,.aib{
  background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.028))!important;
  border:1px solid rgba(255,255,255,.09)!important;border-radius:18px!important;
  box-shadow:0 18px 42px rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.055)!important;
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
}
.card{padding:18px!important;margin-bottom:16px!important;}
.card:hover,.rep-card:hover{border-color:rgba(250,135,61,.36)!important;}
.ct{font-size:13px!important;font-weight:850!important;text-transform:uppercase;letter-spacing:.055em;color:#F2F4FF!important;display:flex;align-items:center;gap:8px;}
.ct:before{content:"";width:9px;height:9px;border-radius:3px;background:linear-gradient(135deg,var(--tcp-orange),var(--tcp-purple));box-shadow:0 0 18px rgba(250,135,61,.55);}
.mgrid{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))!important;gap:14px!important;}
.mc{position:relative;overflow:hidden;padding:18px!important;min-height:118px;}
.mc:before{content:"";position:absolute;inset:0 0 auto;height:4px;background:linear-gradient(90deg,var(--tcp-orange),var(--tcp-purple),var(--tcp-cyan));}
.mc:after{content:"";position:absolute;right:-26px;top:-28px;width:94px;height:94px;border-radius:50%;background:radial-gradient(circle,rgba(250,135,61,.26),transparent 66%);}
.mc .lbl,.chip .cl,.ps-lbl{font-size:10px!important;color:#98A0B6!important;text-transform:uppercase;letter-spacing:.09em;font-weight:800;}
.mc .val,.chip .cv,.ps-val{font-size:22px!important;font-weight:900!important;letter-spacing:-.03em;color:#fff!important;}
.mc .sub,.ps-sub{color:#8992AA!important;}
#dashWidgetContainer{gap:16px!important;}
/* Buttons and form controls */
.sbtn,.gbtn,.pbtn,.view-link,.rbtn,.cbtn-y,.cbtn-n,.ie-save,.ie-cancel{
  border-radius:12px!important;border:1px solid rgba(255,255,255,.13)!important;font-weight:750!important;transition:all .16s ease!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06)!important;
}
.sbtn{background:rgba(255,255,255,.055)!important;color:#F0F3FF!important;}
.gbtn{background:linear-gradient(135deg,rgba(71,209,108,.24),rgba(0,175,239,.14))!important;color:#A7FFC0!important;border-color:rgba(71,209,108,.35)!important;}
.pbtn,.view-link{background:linear-gradient(135deg,rgba(250,135,61,.28),rgba(0,175,239,.16))!important;color:#FFF0E6!important;border-color:rgba(250,135,61,.38)!important;}
.sbtn:hover,.gbtn:hover,.pbtn:hover,.view-link:hover,.ie-save:hover{
  transform:translateY(-1px);background:linear-gradient(135deg,var(--tcp-orange),var(--tcp-violet))!important;color:#fff!important;border-color:rgba(255,255,255,.22)!important;box-shadow:0 12px 24px rgba(250,135,61,.24)!important;
}
.ig label{font-size:10px!important;text-transform:uppercase;letter-spacing:.08em;font-weight:800;color:#929BB2!important;}
.ig input,.ig select,.ig textarea,.filter-row select,.goals-input,.inline-edit-box input,.inline-edit-box select,.inline-edit-box textarea{
  background:rgba(7,9,18,.58)!important;color:#F5F7FF!important;border:1px solid rgba(255,255,255,.13)!important;border-radius:12px!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.04)!important;
}
.ig input:focus,.ig select:focus,.ig textarea:focus,.goals-input:focus{border-color:rgba(250,135,61,.9)!important;box-shadow:0 0 0 3px rgba(250,135,61,.16)!important;}
/* Tables, rows, avatars */
.goals-table th,.qhdr,.pace-hdr{background:rgba(255,255,255,.035)!important;color:#B9C0D3!important;text-transform:uppercase;letter-spacing:.07em;font-size:10px!important;}
.goals-table td,.qrow,.pace-rep-row,.ri,.msr,.log-row{border-color:rgba(255,255,255,.07)!important;}
.goals-table tr:hover td,.qrow:hover,.pace-rep-row:hover,.ri:hover,.msr:hover,.log-row:hover{background:rgba(250,135,61,.075)!important;}
.av{background:linear-gradient(135deg,var(--tcp-orange),var(--tcp-purple) 55%,var(--tcp-cyan))!important;color:#fff!important;font-weight:900!important;box-shadow:0 10px 20px rgba(0,0,0,.26),inset 0 1px 0 rgba(255,255,255,.22)!important;}
.rb,.hrf,.it-badge,.fault-rep,.fault-cust,.fault-other,.note-type-badge,.report-type-badge{border:1px solid rgba(255,255,255,.14);box-shadow:inset 0 1px 0 rgba(255,255,255,.2);}
.pbw,.pace-bar-wrap{background:rgba(255,255,255,.09)!important;}
.pbb,.pace-bar-fill{box-shadow:0 0 16px currentColor;}
.alert-banner{border-width:1px!important;border-radius:16px!important;box-shadow:0 14px 32px rgba(0,0,0,.20)!important;}
/* Image-inspired compact module polish */
.report-card,.note-card,.rv-section{border-radius:15px!important;}
.copy-row,.filter-row{background:rgba(255,255,255,.035)!important;border:1px solid rgba(255,255,255,.075);border-radius:15px!important;padding:10px 12px!important;}
.rep-card.selected{background:linear-gradient(135deg,rgba(250,135,61,.18),rgba(250,135,61,.24))!important;border-color:rgba(250,135,61,.45)!important;}
.rep-card.selected .rc-name{color:#fff!important;}
/* Mobile/tablet: fall back to top scrolling tabs */
@media (max-width:1050px){
  .wrap{padding:12px 12px 26px!important;}
  .tabs{position:relative!important;width:auto!important;display:flex!important;flex-direction:row!important;top:auto!important;bottom:auto!important;left:auto!important;margin:0 0 12px!important;padding:8px 0!important;overflow-x:auto!important;border-right:0!important;border-bottom:1px solid rgba(255,255,255,.08)!important;background:transparent!important;box-shadow:none!important;}
  .tabs:before,.tabs:after{display:none!important;}
  .tab{width:auto!important;font-size:12px!important;padding:8px 11px!important;}
  .top-bar{position:relative!important;margin:-12px -12px 12px!important;padding:14px 12px!important;}
  #dashWidgetContainer{grid-template-columns:1fr!important;}
  .nav-row{width:100%;justify-content:flex-start;}
}
@media print{
  body{background:#fff!important;color:#111!important;}
  .tabs{display:none!important;}
  .wrap{padding:0!important;}
  .top-bar{position:relative!important;box-shadow:none!important;background:#fff!important;color:#111!important;}
