.coach-hero h1{margin:0 0 8px;color:#fff;font-size:28px;line-height:1;font-weight:950;letter-spacing:-.045em;}
.coach-hero p{margin:0;color:#A8AFC3;font-size:13px;line-height:1.6;max-width:800px;}
.coach-hero-actions{position:relative;z-index:1;display:flex;align-items:flex-end;gap:9px;flex-wrap:wrap;justify-content:flex-end;}
.coach-select-wrap{display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid rgba(255,255,255,.10);border-radius:16px;background:rgba(255,255,255,.045);}
.coach-select-wrap label{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:#9FAAD0;font-weight:850;}
.coach-select-wrap select{min-width:220px;border-radius:12px!important;background:rgba(7,9,18,.58)!important;color:#F5F7FF!important;border:1px solid rgba(255,255,255,.13)!important;padding:9px 11px!important;}
.coach-btn{border-radius:12px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.055);color:#F0F3FF;padding:9px 12px;font-size:12px;font-weight:850;cursor:pointer;transition:all .16s ease;}
.coach-btn:hover{transform:translateY(-1px);background:linear-gradient(135deg,var(--tcp-orange,#FA873D),var(--tcp-violet,#FA873D));color:#fff;border-color:rgba(255,255,255,.22);}
.coach-btn.primary{background:linear-gradient(135deg,rgba(250,135,61,.38),rgba(0,175,239,.22));color:#FFF0E6;border-color:rgba(250,135,61,.45);}
.coach-grid{display:grid;grid-template-columns:minmax(320px,.72fr) minmax(0,1.28fr);gap:16px;align-items:start;}
.coach-panel{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.10);border-radius:22px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02)),rgba(19,24,41,.84);box-shadow:0 18px 45px rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.06);padding:18px;}
.coach-panel:before{content:"";position:absolute;inset:0 0 auto;height:4px;background:linear-gradient(90deg,var(--tcp-orange,#FA873D),var(--tcp-purple,#FA873D),var(--tcp-cyan,#00AFEF));}
.coach-panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px;position:relative;z-index:1;}
.coach-panel-title{margin:0;color:#fff;font-size:17px;font-weight:900;letter-spacing:-.025em;}
.coach-muted{font-size:11px;color:#A8AFC3;line-height:1.5;}
.coach-score-card{display:flex;gap:16px;align-items:center;position:relative;z-index:1;}
.coach-score-ring{--score:0;--score-color:#47D16C;width:122px;height:122px;border-radius:999px;display:grid;place-items:center;background:conic-gradient(var(--score-color) calc(var(--score)*1%),rgba(255,255,255,.10) 0);box-shadow:0 18px 42px rgba(0,0,0,.30);position:relative;flex-shrink:0;}
.coach-score-ring:after{content:"";position:absolute;inset:12px;border-radius:999px;background:#151515;border:1px solid rgba(255,255,255,.08);}
.coach-score-ring span{position:relative;z-index:1;font-size:34px;font-weight:950;color:#fff;letter-spacing:-.05em;}
.coach-priority{display:inline-flex;align-items:center;border-radius:999px;padding:5px 10px;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.07em;border:1px solid rgba(255,255,255,.13);}
.coach-priority.green{background:rgba(71,209,108,.12);color:#A7FFC0;border-color:rgba(71,209,108,.35);}
.coach-priority.amber{background:rgba(250,135,61,.12);color:#FFD27A;border-color:rgba(250,135,61,.35);}
.coach-priority.red{background:rgba(250,135,61,.12);color:#FFB3C8;border-color:rgba(250,135,61,.35);}
.coach-kpi-grid{display:grid;grid-template-columns:repeat(5,minmax(145px,1fr));gap:12px;}
.coach-kpi{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.085);border-radius:18px;background:linear-gradient(145deg,rgba(35,48,86,.82),rgba(12,18,35,.95));padding:14px 15px;min-height:116px;}
.coach-kpi:after{content:"";position:absolute;right:-28px;top:-28px;width:92px;height:92px;border-radius:999px;background:radial-gradient(circle,var(--kpi-color,#FA873D),transparent 68%);opacity:.24;}
.coach-kpi .lbl{font-size:10px;color:#98A0B6;text-transform:uppercase;letter-spacing:.09em;font-weight:900;margin-bottom:6px;}
.coach-kpi .val{font-size:24px;font-weight:950;color:#fff;letter-spacing:-.04em;}
.coach-kpi .sub{font-size:11px;color:#A8AFC3;margin-top:5px;line-height:1.35;}
.coach-kpi .mini{height:6px;border-radius:999px;background:rgba(255,255,255,.09);overflow:hidden;margin-top:12px;}
.coach-kpi .mini span{display:block;height:100%;width:var(--pct,0%);background:linear-gradient(90deg,var(--kpi-color,#FA873D),rgba(255,255,255,.50));border-radius:999px;}
.coach-summary{border-left:3px solid #FA873D;background:rgba(250,135,61,.09);border-radius:0 16px 16px 0;padding:14px 16px;color:#F1F1F1;line-height:1.7;font-size:13px;}
.coach-main-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,.45fr);gap:16px;}
.coach-chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}
.coach-chart-card{border:1px solid rgba(255,255,255,.085);border-radius:18px;background:rgba(0,0,0,.16);padding:14px;min-height:260px;}
.coach-chart-title{font-size:12px;font-weight:900;color:#fff;margin-bottom:10px;}
.coach-chart-box{height:210px;}
.coach-list{display:flex;flex-direction:column;gap:8px;}
.coach-list-row{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid rgba(255,255,255,.075);background:rgba(255,255,255,.035);border-radius:14px;padding:10px 12px;}
.coach-list-row strong{color:#fff;font-size:12px;}
.coach-list-row span{font-size:11px;color:#A8AFC3;line-height:1.45;}
.coach-timeline{display:flex;flex-direction:column;gap:9px;max-height:520px;overflow:auto;padding-right:4px;}
.coach-event{display:grid;grid-template-columns:86px 1fr;gap:10px;padding:10px 12px;border-radius:16px;border:1px solid rgba(255,255,255,.075);background:rgba(255,255,255,.035);}
.coach-event-date{font-size:11px;color:#9FAAD0;line-height:1.4;}
.coach-event-tag{display:inline-flex;border-radius:999px;padding:2px 8px;font-size:10px;text-transform:uppercase;font-weight:900;letter-spacing:.05em;margin-bottom:5px;border:1px solid rgba(255,255,255,.12);}
.coach-event-tag.note{background:rgba(250,135,61,.12);color:#FFF0E6;}.coach-event-tag.hr{background:rgba(250,135,61,.12);color:#FFD27A;}.coach-event-tag.quality{background:rgba(250,135,61,.12);color:#FFB3C8;}.coach-event-tag.win{background:rgba(71,209,108,.12);color:#A7FFC0;}
.coach-event-title{font-size:12px;font-weight:900;color:#fff;margin-bottom:2px;}.coach-event-body{font-size:11px;color:#A8AFC3;line-height:1.5;}
.coach-note-input{width:100%;min-height:118px;resize:vertical;background:rgba(7,9,18,.58);color:#F5F7FF;border:1px solid rgba(255,255,255,.13);border-radius:14px;padding:12px;font-family:inherit;font-size:12px;line-height:1.6;}
.coach-empty{padding:22px;text-align:center;color:#A8AFC3;border:1px dashed rgba(255,255,255,.16);border-radius:16px;background:rgba(255,255,255,.025);}
@media(max-width:1200px){.coach-grid,.coach-main-row{grid-template-columns:1fr}.coach-kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr));}.coach-chart-grid{grid-template-columns:1fr}}
@media(max-width:720px){.coach-hero{flex-direction:column;align-items:flex-start;padding:20px}.coach-hero-actions,.coach-select-wrap{width:100%}.coach-select-wrap select{min-width:0;flex:1}.coach-kpi-grid{grid-template-columns:1fr}.coach-score-card{flex-direction:column;align-items:flex-start}.coach-event{grid-template-columns:1fr}}


/* ===== Original style block 041: tcp-v333-coaching-layout-safe-patch ===== */

/* v333 safe layout patch: keep Coaching Center inside the existing app canvas without touching JS */
#pg-coach.page.active{
  display:block!important;
  width:100%!important;
  max-width:100%!important;
  margin:0!important;
  padding:0!important;
  overflow:visible!important;
}
#pg-coach .coach-command{
  width:100%!important;
  max-width:100%!important;
  margin:0!important;
  padding:0!important;
  box-sizing:border-box!important;
}
#pg-coach .coach-hero,
#pg-coach .coach-panel{
  width:100%!important;
  max-width:100%!important;
  box-sizing:border-box!important;
}
#pg-coach .coach-hero{
  align-items:flex-end!important;
}
#pg-coach .coach-grid,
#pg-coach .coach-main-row,
#pg-coach .coach-chart-grid,
#pg-coach .coach-kpi-grid{
  min-width:0!important;
}
#pg-coach .coach-panel,
#pg-coach .coach-chart-card,
#pg-coach .coach-kpi{
  min-width:0!important;
}
#pg-coach canvas{
  max-width:100%!important;
}
/* keep hero controls from forcing the page wider than the content area */
#pg-coach .coach-hero-actions{min-width:0!important;}
#pg-coach .coach-select-wrap{min-width:0!important;}
#pg-coach .coach-select-wrap select{max-width:260px!important;}
@media(max-width:1350px){
  #pg-coach .coach-hero{align-items:flex-start!important;flex-direction:column!important;}
  #pg-coach .coach-hero-actions{justify-content:flex-start!important;width:100%!important;}
}
/* Tracker-themed scrollbars without breaking routing or render functions */
html,body,.tabs,.coach-timeline,.prod-intel-card-row,.prod-card-row,textarea{
  scrollbar-width:thin;
  scrollbar-color:rgba(250,135,61,.75) rgba(255,255,255,.045);
}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-track{background:rgba(255,255,255,.035);border-radius:999px;}
::-webkit-scrollbar-thumb{background:linear-gradient(180deg,rgba(250,135,61,.95),rgba(0,175,239,.75));border-radius:999px;border:2px solid rgba(10,13,24,.95);}
::-webkit-scrollbar-thumb:hover{background:linear-gradient(180deg,rgba(250,135,61,.95),rgba(250,135,61,.95));}


/* ===== Original style block 042: tcp-saas-foundation-v395 ===== */

/* ===== PHASE 1 FOUNDATION — modern SaaS shell ===== */
body{letter-spacing:.005em;}
#tabBar{background:var(--tcp-sidebar);border-right:1px solid var(--tcp-line);}
.nav-group-head{font-size:10px;letter-spacing:.12em;color:#6B7186;font-weight:800;}
.nav-item,.tab{border-radius:9px;transition:background .12s ease,color .12s ease;}
.nav-item:hover,.tab:hover{background:rgba(255,255,255,.05);}
.tab.active,.nav-item.active{background:linear-gradient(90deg,rgba(124,108,255,.16),rgba(124,108,255,.05));box-shadow:inset 2px 0 0 var(--tcp-accent);}
.card,.panel,.meeting-panel,.daily-panel{box-shadow:var(--tcp-shadow-soft);}
button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--tcp-accent);outline-offset:1px;}
::-webkit-scrollbar{width:9px;height:9px;}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:99px;border:2px solid transparent;background-clip:content-box;}
::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,.2);border:2px solid transparent;background-clip:content-box;}
::-webkit-scrollbar-track{background:transparent;}
.page-purpose{display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--tcp-muted);background:linear-gradient(90deg,rgba(124,108,255,.09),transparent 65%);border:1px solid var(--tcp-line);border-left:3px solid var(--tcp-accent);border-radius:10px;padding:8px 13px;margin:0 0 14px;line-height:1.5;}
.page-purpose b{color:var(--tcp-text);font-weight:700;}

/* ===== PHASE 3 — Rep 360 ===== */
.r3-shell{background:var(--tcp-panel);border:1px solid var(--tcp-line);border-radius:16px;padding:0;margin:0 0 16px;box-shadow:var(--tcp-shadow-soft);overflow:hidden;}
.r3-head{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid var(--tcp-line);flex-wrap:wrap;}
.r3-av{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,var(--tcp-violet),var(--tcp-cyan));color:#fff;font-size:14px;font-weight:900;flex:none;}
.r3-name{font-size:16px;font-weight:900;color:var(--tcp-text);}
.r3-sub{font-size:11px;color:var(--tcp-muted);margin-top:2px;}
.r3-hactions{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap;}
.r3-tabs{display:flex;gap:2px;padding:0 12px;border-bottom:1px solid var(--tcp-line);overflow-x:auto;}
.r3-tab{background:transparent;border:0;border-bottom:2px solid transparent;color:var(--tcp-muted);font-size:11.5px;font-weight:800;padding:10px 13px;cursor:pointer;white-space:nowrap;transition:color .12s;}
.r3-tab:hover{color:var(--tcp-text);}
.r3-tab.active{color:var(--tcp-text);border-bottom-color:var(--tcp-accent);}
.r3-pane{display:none;padding:14px 18px;}
.r3-pane.active{display:block;}
.r3-grid5{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;}
.r3-trends{display:grid;grid-template-columns:1fr 1fr;gap:9px;}
.r3-qgrid{display:grid;grid-template-columns:1fr 1fr;gap:18px;}
.r3c-click{cursor:pointer;border-radius:8px;transition:background .12s;}
.r3c-click:hover{background:rgba(255,255,255,.05);}
.r3m-ov{position:fixed;inset:0;background:rgba(4,5,9,.62);backdrop-filter:blur(3px);z-index:1000;display:flex;align-items:center;justify-content:center;padding:18px;}
.r3m-card{position:relative;background:var(--tcp-panel);border:1px solid var(--tcp-line-strong);border-radius:16px;padding:18px 20px 16px;width:min(430px,94vw);max-height:82vh;overflow-y:auto;box-shadow:var(--tcp-shadow);}
.r3m-h{display:flex;align-items:center;gap:9px;margin-bottom:11px;}
.r3m-title{font-size:15px;font-weight:900;color:var(--tcp-text);}
.r3m-row{display:flex;justify-content:space-between;align-items:baseline;gap:12px;padding:7px 0;border-bottom:1px solid var(--tcp-line);font-size:12.5px;color:var(--tcp-text);}
.r3m-row:last-of-type{border-bottom:0;}
.r3m-actions{margin-top:12px;display:flex;gap:8px;}
.r3m-x{position:absolute;top:10px;right:12px;background:transparent;border:0;color:var(--tcp-muted);font-size:22px;cursor:pointer;line-height:1;}
.r3m-x:hover{color:var(--tcp-text);}
@media (max-width:520px){.r3m-ov{align-items:flex-end;padding:0;}.r3m-card{width:100%;border-radius:16px 16px 0 0;max-height:78vh;}}
.r3c-wrap{position:relative;}
.r3c-avg{position:absolute;left:0;right:0;height:0;border-top:1.5px dashed rgba(255,255,255,.28);z-index:1;pointer-events:none;}
.r3c{display:flex;align-items:flex-end;gap:4px;height:92px;position:relative;}
.r3c-c{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;min-width:0;}
.r3c-v{font-size:7.5px;color:var(--tcp-muted);margin-bottom:3px;white-space:nowrap;}
.r3c-b{width:100%;max-width:36px;border-radius:4px 4px 2px 2px;min-height:3px;position:relative;z-index:2;}
.r3c-x{font-size:8.5px;color:var(--tcp-muted);margin-top:5px;white-space:nowrap;}
.r3c-foot{font-size:10px;color:var(--tcp-muted);margin-top:9px;line-height:1.6;}
.r3c-foot b{color:var(--tcp-text);font-weight:800;}
.r3-note{border:1px solid var(--tcp-line);border-radius:10px;padding:8px 11px;margin:0 0 7px;background:var(--tcp-panel-2);}
.r3-note-h{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:10.5px;}
.r3-note-t{font-size:11.5px;color:var(--tcp-text);line-height:1.5;margin-top:4px;}
.r3-pill{background:rgba(124,108,255,.14);color:#FFC69F;font-size:9px;font-weight:900;border-radius:99px;padding:2px 9px;text-transform:uppercase;letter-spacing:.05em;}
.r3-pill-good{background:rgba(52,211,153,.14);color:var(--tcp-green);}
.r3-pill-bad{background:rgba(251,113,133,.14);color:var(--tcp-red);}
.r3-in{background:var(--tcp-panel-2);border:1px solid var(--tcp-line);border-radius:8px;color:var(--tcp-text);font-size:12px;padding:7px 10px;width:100%;box-sizing:border-box;margin-top:6px;}
.r3-addrow{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.r3-tbl{width:100%;border-collapse:collapse;font-size:11.5px;}
.r3-tbl th{text-align:right;padding:7px 9px;border-bottom:1px solid var(--tcp-line-strong);font-size:9px;text-transform:uppercase;letter-spacing:.07em;color:var(--tcp-muted);}
.r3-tbl td{text-align:right;padding:7px 9px;border-bottom:1px solid var(--tcp-line);color:var(--tcp-text);}
@media (max-width:820px){.r3-grid5{grid-template-columns:1fr 1fr;}.r3-trends,.r3-qgrid{grid-template-columns:1fr;}}
/* ===== PHASE 2 — cockpit (dc2) ===== */
.dc2{background:linear-gradient(180deg,rgba(124,108,255,.05),transparent 120px),var(--tcp-panel);border:1px solid var(--tcp-line);border-radius:16px;padding:0;margin:0 0 18px;box-shadow:var(--tcp-shadow-soft);overflow:hidden;}
.dc2-head{display:flex;align-items:center;gap:14px;padding:14px 18px 12px;border-bottom:1px solid var(--tcp-line);flex-wrap:wrap;}
.dc2-eyebrow{font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.12em;color:var(--tcp-accent);}
.dc2-title{font-size:15px;font-weight:700;color:var(--tcp-muted);margin-top:2px;}
.dc2-title b{color:var(--tcp-text);font-weight:900;}
.dc2-status{margin-left:auto;font-size:11px;color:var(--tcp-muted);background:var(--tcp-panel-2);border:1px solid var(--tcp-line);border-radius:99px;padding:6px 13px;white-space:nowrap;}
.dc2-actions{display:flex;gap:6px;}
.dc2-act{display:inline-flex;align-items:center;gap:5px;background:transparent;border:1px solid var(--tcp-line);color:var(--tcp-muted);font-size:11px;font-weight:700;border-radius:9px;padding:6px 11px;cursor:pointer;transition:all .12s;}
.dc2-act:hover{color:var(--tcp-text);border-color:var(--tcp-accent);background:rgba(124,108,255,.08);}
.dc2-sel{max-width:110px;}
.dc2-stats{display:grid;grid-template-columns:repeat(4,1fr);padding:14px 18px;gap:0;border-bottom:1px solid var(--tcp-line);}
.dc2-stat{padding:0 18px;border-left:1px solid var(--tcp-line);min-width:0;}
.dc2-stat:first-child{padding-left:0;border-left:0;}
.dc2-sl{font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--tcp-muted);}
.dc2-sv{font-size:23px;font-weight:900;letter-spacing:-.03em;color:var(--tcp-text);margin-top:4px;line-height:1;white-space:nowrap;}
.dc2-dim{color:var(--tcp-muted);font-weight:700;font-size:16px;}
.dc2-ss{font-size:10.5px;margin-top:5px;}
.dc-up{color:var(--tcp-green);font-weight:800;}.dc-down{color:var(--tcp-red);font-weight:800;}.dc-flat{color:var(--tcp-muted);}
.dc2-body{display:grid;grid-template-columns:1.35fr 1fr;border-bottom:1px solid var(--tcp-line);}
.dc2-brief{padding:13px 18px;border-right:1px solid var(--tcp-line);}
.dc2-attn{padding:13px 18px 10px;}
.dc2-panel-h{display:flex;align-items:center;justify-content:space-between;font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--tcp-muted);margin-bottom:9px;}
.dc2-count{background:rgba(124,108,255,.15);color:#FFC69F;font-size:9.5px;font-weight:900;border-radius:99px;padding:2px 9px;}
.dc-mini{background:transparent;border:1px solid var(--tcp-line);color:var(--tcp-muted);font-size:11px;border-radius:7px;padding:2px 8px;cursor:pointer;}
.dc-mini:hover{color:var(--tcp-text);border-color:var(--tcp-accent);}
.dc-brief-txt{font-size:12.5px;line-height:1.6;color:var(--tcp-text);}
.dc-pri{list-style:none;margin:9px 0 0;padding:0;}
.dc-pri li{position:relative;padding-left:16px;font-size:11.5px;line-height:1.5;margin:5px 0;color:var(--tcp-text);}
.dc-pri li:before{content:"\2192";position:absolute;left:0;color:var(--tcp-accent);font-weight:900;}
.dc2-al{display:flex;align-items:center;gap:9px;padding:7px 9px;margin:0 -9px;border-radius:9px;font-size:11.5px;color:var(--tcp-text);cursor:pointer;transition:background .12s;}
.dc2-al:hover{background:rgba(255,255,255,.04);}
.dc2-al-static{cursor:default;}
.dc2-al-static:hover{background:transparent;}
.dc2-dot{width:7px;height:7px;border-radius:50%;flex:none;}
.dc2-red{background:var(--tcp-red);box-shadow:0 0 8px rgba(251,113,133,.5);}
.dc2-amber{background:var(--tcp-gold);box-shadow:0 0 8px rgba(251,191,36,.4);}
