/* ===== Original style block 043: tcp-phase5-visual-mobile-v409 ===== */

/* ===== PHASE 5 — visual unification + full mobile ===== */
body{-webkit-tap-highlight-color:transparent;}
/* section titles: quiet eyebrows instead of plain labels */
.ct{font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.09em;color:var(--tcp-muted);margin-bottom:11px;display:flex;align-items:center;gap:7px;flex-wrap:wrap;}
/* legacy buttons -> one language */
.sbtn,.rbtn,.pbtn,.dash-action-btn,.wk-help-btn,.meeting-btn{border-radius:9px;border:1px solid var(--tcp-line);background:var(--tcp-panel-2);color:var(--tcp-text);transition:border-color .12s ease,background .12s ease,transform .06s ease;}
.sbtn:hover,.rbtn:hover,.pbtn:hover,.dash-action-btn:hover,.meeting-btn:hover{border-color:var(--tcp-accent);background:rgba(124,108,255,.10);}
.sbtn:active,.rbtn:active,.pbtn:active,.dash-action-btn:active{transform:translateY(1px);}
.sbtn.entry-primary,.meeting-btn.primary{background:linear-gradient(135deg,var(--tcp-violet),#5B8CFF);border-color:transparent;color:#fff;font-weight:800;}
.sbtn.entry-primary:hover,.meeting-btn.primary:hover{filter:brightness(1.08);background:linear-gradient(135deg,var(--tcp-violet),#5B8CFF);}
.sbtn.entry-danger{background:rgba(251,113,133,.10);border-color:rgba(251,113,133,.38);color:var(--tcp-red);}
.sbtn.entry-danger:hover{background:rgba(251,113,133,.16);border-color:var(--tcp-red);}
/* inputs and selects */
input,select,textarea{border-radius:9px;}
select.nav-sel{background:var(--tcp-panel-2);border:1px solid var(--tcp-line);color:var(--tcp-text);}
/* ===== nav strip on tablets/phones (builds on the existing <=1050 transform) ===== */
@media(max-width:1050px){
  .tabs#tabBar{position:sticky;top:0;z-index:60;display:flex;overflow-x:auto;-webkit-overflow-scrolling:touch;gap:6px;padding:9px 10px;border-right:0!important;border-bottom:1px solid var(--tcp-line);background:rgba(12,13,18,.92);backdrop-filter:blur(10px);scrollbar-width:none;}
  .tabs#tabBar::-webkit-scrollbar{display:none;}
  #tabBar .tab{flex:0 0 auto;min-height:38px;padding:8px 14px;border-radius:99px;border:1px solid var(--tcp-line);font-size:12px;}
  #tabBar .tab.active{background:rgba(124,108,255,.18);box-shadow:none;border-color:rgba(124,108,255,.55);}
  /* bring the global period selectors BACK on mobile (they were display:none) */
  .nav-controls{display:flex!important;flex-wrap:wrap;align-items:center;gap:6px;padding:6px 10px 2px;}
  .nav-controls .nav-lbl{font-size:8.5px;letter-spacing:.08em;}
  .nav-controls .nav-sel{min-height:34px;font-size:12px;max-width:130px;}
}
/* ===== phone layer ===== */
@media(max-width:820px){
  .page{padding-left:2px;padding-right:2px;}
  .card{overflow-x:auto;padding:.8rem .85rem;}
  .card table{min-width:540px;}
  .r3-grid5{grid-template-columns:1fr 1fr;}
  .r3-head,.dc2-head{padding:12px 14px;}
  .dc2-stats{padding:12px 14px;}
  .dc2-brief,.dc2-attn,.dc2-chart,.dc2-repai,.r3-pane{padding:12px 14px;}
  h1{font-size:20px;}
  .r3-hactions .dc2-act span{display:none;}
}
@media(max-width:520px){
  .dcb-x,.r3c-x{font-size:7px;}
  .dc2-sv{font-size:19px;}
  .r3-addrow{grid-template-columns:1fr;}
}


