#rp-overlay .rp2-ac-history-cell{color:#8291a7;font-size:8.8px}
#rp-overlay .rp2-ac-history-cell strong{color:#fff;font-size:9.8px}
#rp-overlay .rp2-ac-history-focus{color:#c5cfdd;font-size:9px;line-height:1.45}

#rp-overlay .rp2-ac-source-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
#rp-overlay .rp2-ac-source{padding:15px;border-radius:15px;border:1px solid rgba(255,255,255,.055);background:rgba(255,255,255,.022)}
