#rp-overlay .rp2-ac-source.off{opacity:.56}
#rp-overlay .rp2-ac-source-label{color:#718099;font-size:7.5px;font-weight:950;letter-spacing:.8px;text-transform:uppercase}
#rp-overlay .rp2-ac-source-value{margin-top:7px;color:#fff;font-size:12px;font-weight:920}
#rp-overlay .rp2-ac-source-copy{margin-top:5px;color:#76869c;font-size:8.3px;line-height:1.45}

#rp-overlay .rp2-ac-empty{padding:34px;border-radius:18px;border:1px dashed rgba(255,255,255,.10);background:rgba(255,255,255,.02);text-align:center}
#rp-overlay .rp2-ac-empty strong{display:block;color:#fff;font-size:15px}
