@media(max-width:1650px){#rp-overlay .rp2-ac-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:1380px){
  #rp-overlay .rp2-ac-hero-grid,#rp-overlay .rp2-ac-grid-2,#rp-overlay .rp2-ac-chat-layout{grid-template-columns:1fr}
  #rp-overlay .rp2-ac-score-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
