  #rp-overlay .rp2-ac-kpis,#rp-overlay .rp2-ac-score-grid,#rp-overlay .rp2-ac-grid-3,#rp-overlay .rp2-ac-grid-4,#rp-overlay .rp2-ac-source-grid,#rp-overlay .rp2-ac-cadence{grid-template-columns:1fr}
