/* ===== Original style block 122: tcp-brand-standards-v539 ===== */

@import url('https://fonts.googleapis.com/css2?family=Droid+Serif:wght@700&family=Open+Sans:wght@400;600;700;800&display=swap');

/* ==========================================================================
   TRIPLE CROWN PRODUCTS BRAND STANDARDS · BUILD v539

   Primary:      TCP Orange #FA873D · Black #000000 · White #FFFFFF
   Complement:   Cool Gray 9 #666666 · Process Cyan #00AFEF
   Typography:   Droid Serif Bold · Open Sans
   ========================================================================== */

:root{
  --tcp-bg-0:#050505;
  --tcp-bg-1:#0B0B0B;
  --tcp-bg-2:#121212;
  --tcp-sidebar:#0B0B0B;
  --tcp-panel:#151515;
  --tcp-panel-2:#202020;
  --tcp-panel-3:#292929;
  --tcp-line:rgba(255,255,255,.08);
  --tcp-line-strong:rgba(102,102,102,.52);
  --tcp-text:#FFFFFF;
  --tcp-muted:#A7A7A7;
  --tcp-orange:#FA873D;
  --tcp-purple:#FA873D;
  --tcp-violet:#FA873D;
  --tcp-cyan:#00AFEF;
  --tcp-blue:#00AFEF;
  --tcp-accent:#FA873D;
  --tcp-brand-orange:#FA873D;
  --tcp-brand-cyan:#00AFEF;
  --tcp-brand-gray:#666666;
  --color-background-primary:#151515;
  --color-background-secondary:#202020;
  --color-background-info:#16252B;
  --color-border-tertiary:rgba(255,255,255,.08);
  --color-border-secondary:rgba(102,102,102,.65);
  --color-text-primary:#FFFFFF;
  --color-text-secondary:#A7A7A7;
  --color-text-info:#66D4FA;
}

html,body,input,select,textarea,button{
  font-family:'Open Sans',Arial,sans-serif!important;
}
html{background:#000!important}
html body{
  background:
    radial-gradient(circle at 14% 2%,rgba(250,135,61,.19) 0,transparent 28rem),
    radial-gradient(circle at 89% 0%,rgba(0,175,239,.13) 0,transparent 33rem),
    radial-gradient(circle at 82% 88%,rgba(250,135,61,.06) 0,transparent 31rem),
    linear-gradient(135deg,#000 0%,#0B0B0B 45%,#050505 100%)!important;
  color:#fff!important;
}
h1,h2,.dash-hero h1,.entry-hero h1,.reviews-hero h1,.reports-hero h1,
.hr-hero h1,.credit-hero h1,.art-hero h1,.admin-hero h1,.at537-hero h1,
#rp-overlay .rp2-title,#rp-overlay .cw4-name,#rp-overlay .cw5-name{
  font-family:'Droid Serif',Georgia,serif!important;
  font-weight:700!important;
}

/* Manager navigation and header */
.tabs{
  background:
    linear-gradient(180deg,rgba(15,15,15,.99),rgba(0,0,0,.995)),
    radial-gradient(circle at 10% 0%,rgba(250,135,61,.22),transparent 18rem)!important;
  border-right-color:rgba(102,102,102,.42)!important;
}
.tabs:before{
  font-family:'Droid Serif',Georgia,serif!important;
  background:linear-gradient(135deg,#FA873D,#FA873D 54%,#00AFEF) 0 6px/38px 38px no-repeat!important;
  filter:drop-shadow(0 0 18px rgba(250,135,61,.34))!important;
}
.tabs:after{color:#777!important}
.tab{color:#D9D9D9!important}
.tab.active{
  background:linear-gradient(90deg,#FA873D,#E96E20 52%,#00AFEF)!important;
  color:#fff!important;
  border-color:rgba(255,255,255,.18)!important;
  box-shadow:0 12px 28px rgba(250,135,61,.24),inset 0 1px 0 rgba(255,255,255,.24)!important;
}
.tab:hover:not(.active){
  background:rgba(250,135,61,.07)!important;
  border-color:rgba(250,135,61,.18)!important;
}
#tabBar .tab[style]{border-color:rgba(0,175,239,.28)!important;color:#AEEAFF!important}
.top-bar{
  background:linear-gradient(180deg,rgba(5,5,5,.95),rgba(5,5,5,.78))!important;
  border-bottom-color:rgba(102,102,102,.38)!important;
}
.top-bar > div:first-child span:first-child{
  font-family:'Droid Serif',Georgia,serif!important;
  background:linear-gradient(90deg,#fff,#fff 55%,#66D4FA)!important;
  -webkit-background-clip:text!important;background-clip:text!important;color:transparent!important;
}
.top-bar > div:first-child:after{color:#777!important}
.nav-row{background:rgba(255,255,255,.025)!important;border-color:rgba(102,102,102,.38)!important}
.qbadge{background:linear-gradient(135deg,rgba(250,135,61,.23),rgba(0,175,239,.16))!important;color:#FFF0E6!important}
.wr{color:#66D4FA!important}

/* Manager cards */
.card,.mc,.profile-stat,.chip,.rv-section,.report-card,.note-card,.rep-card,.aib{
  background:linear-gradient(180deg,rgba(255,255,255,.052),rgba(255,255,255,.018)),rgba(18,18,18,.95)!important;
  border-color:rgba(102,102,102,.38)!important;
}
.card:hover,.rep-card:hover{border-color:rgba(250,135,61,.38)!important}
.ct:before{background:linear-gradient(135deg,#FA873D,#00AFEF)!important;box-shadow:0 0 18px rgba(250,135,61,.46)!important}
.mc:before{background:linear-gradient(90deg,#FA873D,#FA873D,#00AFEF)!important}
