.mc .lbl,.chip .cl,.ps-lbl{color:#A8A8A8!important}
.pbtn,.view-link{
  background:linear-gradient(135deg,rgba(250,135,61,.24),rgba(0,175,239,.10))!important;
  color:#FFF0E6!important;
  border-color:rgba(250,135,61,.38)!important;
}
.sbtn:hover,.gbtn:hover,.pbtn:hover,.view-link:hover,.ie-save:hover{
  background:linear-gradient(135deg,#FA873D,#00AFEF)!important;
