#rp-overlay .ce540-card{width:min(850px,96vw);max-height:92vh;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;border-radius:17px;border:1px solid rgba(102,102,102,.55);background:#f8fafc;color:#172033;box-shadow:0 32px 100px rgba(0,0,0,.65);overflow:hidden}
#rp-overlay .ce540-head{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 14px;background:linear-gradient(90deg,#E96E20,#FA873D 54%,#00AFEF);color:#fff}
#rp-overlay .ce540-head strong{font-family:'Droid Serif',Georgia,serif;font-size:13px}
#rp-overlay .ce540-head span{display:block;margin-top:2px;font-size:8px;color:#fff3e9}
#rp-overlay .ce540-close{width:31px;height:31px;border:0;border-radius:7px;background:rgba(255,255,255,.14);color:#fff;font-weight:950;cursor:pointer}
#rp-overlay .ce540-fields{display:grid;background:#fff;border-bottom:1px solid #dbe1e9}
#rp-overlay .ce540-line{display:grid;grid-template-columns:65px minmax(0,1fr);gap:8px;align-items:center;min-height:43px;padding:4px 13px;border-bottom:1px solid #edf0f5}
#rp-overlay .ce540-line label{color:#536174;font-size:10px;font-weight:800}
#rp-overlay .ce540-line input{width:100%;border:0;outline:0;background:transparent;color:#172033;font-size:11px}
#rp-overlay .ce540-body{min-height:330px;padding:16px;overflow:auto;outline:0;background:#fff;color:#1f2937;font-size:12px;line-height:1.65}
#rp-overlay .ce540-foot{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:10px 13px;border-top:1px solid #d7dde6;background:#f2f5f8}
#rp-overlay .ce540-foot span{color:#64748b;font-size:8px}
#rp-overlay .ce540-actions{display:flex;gap:7px}
#rp-overlay .ce540-btn{min-height:37px;padding:0 12px;border-radius:8px;border:1px solid #cfd6df;background:#fff;color:#334155;font-size:9px;font-weight:900;cursor:pointer}
#rp-overlay .ce540-btn.send{border:0;background:linear-gradient(135deg,#FA873D,#00AFEF);color:#fff}

/* Admin integration placeholder */
.tcp540-admin{margin-top:16px;padding:18px;border-radius:18px;border:1px solid rgba(250,135,61,.22);background:linear-gradient(135deg,rgba(250,135,61,.07),rgba(0,175,239,.035)),rgba(15,15,15,.94)}
.tcp540-admin h3{font-family:'Droid Serif',Georgia,serif;color:#fff;font-size:18px;margin:0}
.tcp540-admin p{margin:6px 0 0;color:#999;font-size:11px;line-height:1.55}
.tcp540-admin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}
.tcp540-admin-field{display:grid;gap:5px}
.tcp540-admin-field label{color:#aaa;font-size:9px;font-weight:800;text-transform:uppercase}
.tcp540-admin-field input,.tcp540-admin-field select,.tcp540-admin-field textarea{width:100%;min-height:40px;padding:8px 10px;border-radius:10px;border:1px solid rgba(102,102,102,.6);background:#0c0c0c;color:#fff;font:11px 'Open Sans',Arial,sans-serif}
.tcp540-admin-field textarea{min-height:74px;resize:vertical}
.tcp540-admin-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}

@media(max-width:1450px){
 #rp-overlay .cl2-workbench{grid-template-columns:minmax(240px,.55fr) minmax(570px,1.35fr)}
 #rp-overlay .cl2-right{grid-column:1/-1}
 #rp-overlay .cl2-right .cl2-body{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}
 #rp-overlay .cl2-right .cl2-promo,#rp-overlay .cl2-right .cl2-talk{margin-top:0}
}
@media(max-width:1050px){
 #rp-overlay .cl2-hero-top,#rp-overlay .cl2-workbench{grid-template-columns:1fr}
 #rp-overlay .cl2-hero-status{min-width:0}
 #rp-overlay .cl2-right .cl2-body{grid-template-columns:1fr 1fr}
}
@media(max-width:720px){
 #rp-overlay .cl2-record-grid,#rp-overlay .cl2-grid-2,#rp-overlay .cl2-grid-3,#rp-overlay .cl2-filter-row,#rp-overlay .cl2-right .cl2-body,.tcp540-admin-grid{grid-template-columns:1fr}
 #rp-overlay .cl2-art-record{grid-template-columns:1fr}
 #rp-overlay .cl2-art-image{width:100%;height:130px}
 #rp-overlay .cl2-active-row,#rp-overlay .cl2-complete-top{align-items:flex-start;flex-direction:column}
}


