  display:none!important;
}
#rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-workbench{
  grid-template-columns:minmax(620px,1.5fr) minmax(340px,.78fr)!important;
  align-items:start!important;
}
#rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-center{
  grid-column:1!important;
}
#rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-context{
  grid-column:2!important;
}
@media(max-width:1450px){
  #rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-workbench{
    grid-template-columns:minmax(0,1fr) minmax(320px,400px)!important;
  }
  #rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-context{
    grid-column:2!important;
  }
}
@media(max-width:1180px){
  #rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-workbench{
    grid-template-columns:1fr!important;
  }
  #rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-center,
  #rp-overlay .rp2-app.rp2-mode-phased #rp2-page .ps62-context{
    grid-column:auto!important;
  }
}


/* ===== Original style block 157: cx586-brief-tabs ===== */

.cx586-tabs{position:relative;display:flex;gap:4px;margin-top:14px;padding:4px;border:1px solid rgba(255,255,255,.09);border-radius:13px;background:rgba(4,10,19,.4);}
.cx586-tab{flex:1;min-height:32px;border:0;border-radius:10px;background:transparent;color:#8797AD;font-size:10.5px;font-weight:900;letter-spacing:.4px;text-transform:uppercase;cursor:pointer;transition:.15s ease;}
.cx586-tab.on{background:linear-gradient(135deg,rgba(0,175,239,.22),rgba(0,175,239,.08));color:#EAF6FF;box-shadow:inset 0 1px 0 rgba(255,255,255,.1);}
.cx586-saved{position:absolute;right:10px;top:-20px;color:#47D16C;font-size:9px;font-weight:900;opacity:0;transition:opacity .3s;}
.cx586-pane{display:none;margin-top:11px;}
.cx586-pane.on{display:block;animation:cux8Content .2s ease both;}
.cx586-editable span{display:flex!important;align-items:center;gap:6px;}
.cx586-pencil{border:0;background:transparent;color:#00AFEF;font-size:11px;cursor:pointer;padding:0 2px;line-height:1;opacity:.75;}
.cx586-pencil:hover{opacity:1;transform:scale(1.15);}
.cx586-edit-in{width:100%;box-sizing:border-box;margin-top:4px;padding:6px 8px;border-radius:8px;border:1px solid rgba(0,175,239,.5);background:rgba(0,20,35,.6);color:#fff;font-size:11px;font-weight:800;outline:none;}
.cx586-vrow{display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:9px 2px;border-bottom:1px solid rgba(255,255,255,.06);}
.cx586-vl{color:#718097;font-size:8.6px;font-weight:950;text-transform:uppercase;letter-spacing:.7px;}
.cx586-vv{color:#F0F5FC;font-size:12.5px;font-weight:900;text-align:right;}
.cx586-vv em{display:block;color:#8797AD;font-size:9.4px;font-weight:600;font-style:normal;margin-top:2px;}
.cx586-due{color:#FA873D;}
.cx586-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:7px;}
.cx586-chip{padding:6px 9px;border-radius:999px;border:1px solid rgba(71,209,108,.28);background:rgba(71,209,108,.08);color:#C9F5D8;font-size:9.6px;font-weight:800;}
.cx586-chip b{color:#7BF0A5;}
.cx586-vempty{color:#718097;font-size:9.6px;margin-top:6px;}
.cx586-health-line{display:flex;align-items:center;gap:8px;margin-top:13px;padding:9px 12px;border:1px solid;border-radius:12px;background:rgba(255,255,255,.02);color:#DCE6F2;font-size:11px;font-weight:850;}
.cx586-dot{width:8px;height:8px;border-radius:50%;box-shadow:0 0 10px currentColor;flex:none;}


/* ===== Original style block 158: cxp588-products ===== */

.cxp588-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:2px 0 12px;}
.cxp588-stat{border:1px solid rgba(255,255,255,.09);border-radius:14px;background:linear-gradient(160deg,rgba(13,22,36,.9),rgba(7,12,22,.94));padding:11px 13px;}
.cxp588-stat span{display:block;color:#718097;font-size:8.6px;font-weight:950;text-transform:uppercase;letter-spacing:.7px;}
.cxp588-stat strong{display:block;margin-top:4px;color:#F0F5FC;font-size:19px;font-weight:900;line-height:1.05;}
.cxp588-stat em{display:block;margin-top:3px;color:#8797AD;font-size:9.4px;font-style:normal;}
.cxp588-actions{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px;}
.cxp588-cath{margin:4px 0 9px;color:#9DDCFF;font-size:9.6px;font-weight:950;text-transform:uppercase;letter-spacing:.8px;}
.cxp588-cats{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px;}
.cxp588-cat{position:relative;display:flex;flex-direction:column;align-items:center;gap:0;padding:20px 15px 14px;border:1px solid color-mix(in srgb,var(--c,#4C9DFF) 38%,transparent);border-radius:18px;background:radial-gradient(90% 70% at 50% 0%,color-mix(in srgb,var(--c,#4C9DFF) 14%,transparent),transparent 70%),linear-gradient(160deg,rgba(14,24,40,.92),rgba(7,12,22,.95));cursor:pointer;text-align:center;transition:.16s;}
.cxp588-cat:hover{border-color:color-mix(in srgb,var(--c,#4C9DFF) 75%,transparent);transform:translateY(-2px);box-shadow:0 12px 30px rgba(0,0,0,.4),0 0 24px color-mix(in srgb,var(--c,#4C9DFF) 18%,transparent);}
.cxp588-cat-ic{display:flex;align-items:center;justify-content:center;width:52px;height:52px;border-radius:16px;font-size:25px;line-height:1;background:color-mix(in srgb,var(--c,#4C9DFF) 20%,rgba(255,255,255,.03));border:1px solid color-mix(in srgb,var(--c,#4C9DFF) 45%,transparent);box-shadow:0 0 22px color-mix(in srgb,var(--c,#4C9DFF) 30%,transparent);}
.cxp588-cat strong{margin-top:11px;color:#F0F5FC;font-size:16px;font-weight:900;letter-spacing:.2px;}
.cxp588-cat-copy{margin-top:4px;color:#8797AD;font-size:9.6px;min-height:12px;max-width:92%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.cxp588-cat-meta{display:flex;align-items:center;gap:7px;margin-top:12px;padding-top:11px;border-top:1px solid rgba(255,255,255,.07);width:100%;justify-content:center;}
.cxp588-cat-meta b{display:flex;align-items:center;justify-content:center;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:color-mix(in srgb,var(--c,#4C9DFF) 25%,transparent);border:1px solid color-mix(in srgb,var(--c,#4C9DFF) 55%,transparent);color:#fff;font-size:9.6px;font-weight:950;}
.cxp588-cat-meta i{color:color-mix(in srgb,var(--c,#4C9DFF) 80%,#fff);font-size:8.8px;font-weight:950;font-style:normal;text-transform:uppercase;letter-spacing:.6px;}
.cxp588-cat-arrow{display:flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;border:1px solid color-mix(in srgb,var(--c,#4C9DFF) 55%,transparent);color:color-mix(in srgb,var(--c,#4C9DFF) 85%,#fff);font-size:12px;margin-left:2px;transition:.15s;}
.cxp588-cat:hover .cxp588-cat-arrow{background:color-mix(in srgb,var(--c,#4C9DFF) 25%,transparent);transform:translateX(2px);}
.cxp588-cat-due{position:absolute;top:10px;right:10px;padding:3px 9px;border-radius:999px;border:1px solid rgba(250,135,61,.5);background:rgba(250,135,61,.12);color:#FFC79A;font-size:8.6px;font-weight:950;text-transform:uppercase;letter-spacing:.4px;}
.cxp588-banner{position:relative;margin:2px 0 12px;padding:20px 20px 16px;border:1px solid rgba(255,255,255,.1);border-radius:18px;background:linear-gradient(120deg,rgba(0,175,239,.14),rgba(7,12,22,.9) 55%),linear-gradient(160deg,rgba(14,24,40,.92),rgba(7,12,22,.95));overflow:hidden;}
.cxp588-backbtn{border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.05);color:#C7D6EA;border-radius:999px;padding:6px 13px;font-size:10px;font-weight:900;cursor:pointer;margin-bottom:8px;}
.cxp588-backbtn:hover{border-color:rgba(0,175,239,.5);color:#fff;}
.cxp588-banner-word{font-size:clamp(30px,4.6vh,44px);font-weight:950;letter-spacing:.5px;line-height:1;color:#F0F5FC;text-transform:uppercase;text-shadow:0 2px 24px rgba(0,175,239,.35);}
.cxp588-banner-stats{display:flex;gap:22px;flex-wrap:wrap;margin-top:13px;}
.cxp588-banner-stats>div{min-width:86px;}
.cxp588-banner-stats span{display:block;color:#7f96b3;font-size:8.4px;font-weight:950;text-transform:uppercase;letter-spacing:.7px;}
.cxp588-banner-stats strong{display:block;margin-top:3px;color:#EAF4FF;font-size:16.5px;font-weight:900;}
.cxp588-banner-stats em{display:block;color:#8fa8c6;font-size:9.2px;font-style:normal;margin-top:1px;}
.cxp588-topsku{max-width:170px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13.5px!important;}
.cxp588-filter{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 11px;}
.cxp588-in{flex:1;min-width:170px;box-sizing:border-box;padding:9px 12px;border-radius:11px;border:1px solid rgba(255,255,255,.11);background:rgba(4,10,19,.55);color:#EAF2FC;font-size:11.5px;font-weight:650;outline:none;}
.cxp588-in:focus{border-color:rgba(0,175,239,.5);}
.cxp588-count{color:#718097;font-size:10px;font-weight:800;white-space:nowrap;}
.cxp588-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(196px,1fr));gap:12px;}
.cxp588-card{position:relative;display:flex;flex-direction:column;border:1px solid rgba(255,255,255,.09);border-radius:16px;background:linear-gradient(160deg,rgba(13,22,36,.85),rgba(7,12,22,.92));padding:12px;transition:.16s;}
.cxp588-card:hover{border-color:rgba(0,175,239,.42);transform:translateY(-2px);}
.cxp588-card-check{position:absolute;top:10px;left:10px;z-index:2;}
.cxp588-cb{width:17px;height:17px;accent-color:#FA873D;cursor:pointer;}
.cxp588-card-pill{position:absolute;top:10px;right:10px;z-index:2;padding:3px 9px;border:1px solid;border-radius:999px;font-size:8.4px;font-weight:950;letter-spacing:.4px;text-transform:uppercase;background:rgba(5,9,16,.75);}
.cxp588-card-img{display:flex;align-items:center;justify-content:center;height:108px;border:0;border-radius:12px;background:rgba(255,255,255,.045);cursor:pointer;overflow:hidden;margin:14px 0 9px;}
.cxp588-card-img img{max-width:100%;max-height:100%;object-fit:contain;}
.cxp588-card-emoji{font-size:40px;opacity:.85;}
.cxp588-card-name{background:none;border:0;padding:0;color:#F0F5FC;font-size:12.5px;font-weight:900;text-align:left;cursor:pointer;line-height:1.25;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
.cxp588-card-name:hover{color:#7CD7FF;}
.cxp588-card-sku{color:#8797AD;font-size:9.2px;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.cxp588-card-kpis{display:grid;grid-template-columns:1fr 1fr 1.2fr;gap:6px;margin-top:9px;padding-top:9px;border-top:1px solid rgba(255,255,255,.07);}
.cxp588-card-kpis span{display:block;color:#718097;font-size:7.8px;font-weight:950;text-transform:uppercase;letter-spacing:.5px;}
.cxp588-card-kpis strong{display:block;color:#E6EEF8;font-size:10.6px;font-weight:850;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.cxp588-card-ago{margin-top:6px;color:#74849D;font-size:8.8px;}
.cxp588-card-quote{margin-top:9px;padding:8px 0;border-radius:10px;border:1px solid rgba(250,135,61,.45);background:rgba(250,135,61,.1);color:#FFC79A;font-size:10px;font-weight:900;cursor:pointer;}
.cxp588-card-quote:hover{background:rgba(250,135,61,.22);}
.cxp588-empty{border:1px dashed rgba(255,255,255,.14);border-radius:13px;padding:16px;color:#9AA7BC;font-size:11.5px;line-height:1.6;margin:4px 0 10px;}
.cxp588-opp-h{margin:16px 0 8px;color:#9DDCFF;font-size:9.6px;font-weight:950;text-transform:uppercase;letter-spacing:.8px;}
.cxp588-chips{display:flex;flex-wrap:wrap;gap:8px;}
.cxp588-chip{display:flex;flex-direction:column;align-items:flex-start;gap:2px;max-width:280px;padding:9px 12px;border-radius:13px;border:1px solid rgba(76,157,255,.32);background:rgba(76,157,255,.07);cursor:pointer;text-align:left;transition:.15s;}
.cxp588-chip:hover{border-color:rgba(76,157,255,.6);background:rgba(76,157,255,.13);}
.cxp588-chip b{color:#BFDCFF;font-size:11px;font-weight:900;}
.cxp588-chip span{color:#8FA5C2;font-size:9.2px;line-height:1.45;}
.cxp588-chip.covered{border-color:rgba(71,209,108,.3);background:rgba(71,209,108,.06);}
.cxp588-chip.covered b{color:#B8F0CB;}
.cxp588-bar{position:sticky;bottom:10px;display:none;gap:10px;align-items:center;justify-content:flex-end;margin-top:12px;padding:10px 14px;border:1px solid rgba(250,135,61,.4);border-radius:14px;background:rgba(20,12,6,.92);backdrop-filter:blur(8px);box-shadow:0 8px 30px rgba(0,0,0,.5);z-index:5;}
.cxp588-bar-note{margin-right:auto;color:#FFC79A;font-size:10px;font-weight:950;text-transform:uppercase;letter-spacing:.6px;}
#cxp588-cart{position:fixed;inset:0;z-index:100000;display:none;align-items:center;justify-content:center;background:rgba(2,5,10,.6);backdrop-filter:blur(4px);}
.cxp588-cart-panel{width:min(480px,92vw);max-height:78vh;display:flex;flex-direction:column;border:1px solid rgba(250,135,61,.35);border-radius:18px;background:linear-gradient(165deg,#141d2e,#0a0f1a);box-shadow:0 24px 70px rgba(0,0,0,.6);overflow:hidden;}
.cxp588-cart-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid rgba(255,255,255,.08);}
.cxp588-cart-head span{color:#FFC79A;font-size:11px;font-weight:950;text-transform:uppercase;letter-spacing:.7px;}
.cxp588-cart-x{border:0;background:transparent;color:#8797AD;font-size:14px;cursor:pointer;}
#cxp588-cart-list{flex:1;overflow:auto;padding:10px 14px;display:flex;flex-direction:column;gap:8px;}
.cxp588-cart-row{display:flex;align-items:center;gap:10px;border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:9px 11px;background:rgba(255,255,255,.02);}
.cxp588-cart-ic{font-size:18px;}
.cxp588-cart-main{flex:1;min-width:0;}
.cxp588-cart-main strong{display:block;color:#F0F5FC;font-size:11.5px;font-weight:850;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.cxp588-cart-main span{display:block;color:#8797AD;font-size:9px;margin-top:1px;}
.cxp588-cart-rev{color:#BFDCFF;font-size:10.5px;font-weight:850;white-space:nowrap;}
.cxp588-cart-rm{border:0;background:transparent;color:#FB7185;font-size:11px;cursor:pointer;padding:4px;}
.cxp588-cart-empty{color:#8797AD;font-size:10.6px;padding:14px 4px;line-height:1.6;}
.cxp588-cart-foot{display:flex;gap:9px;justify-content:flex-end;padding:12px 14px;border-top:1px solid rgba(255,255,255,.08);}
@media(max-width:900px){.cxp588-stats{grid-template-columns:1fr 1fr;}.cxp588-banner-word{font-size:26px;}}

