  .cxp588-flip{transition:transform .34s cubic-bezier(.22,.8,.3,1)!important;}
}
@keyframes cxp588SlideIn{from{transform:translateX(105%);}to{transform:translateX(0);}}


/* ===== Original style block 159: tb605-todays-business ===== */

/* greeting bar */
#rp-overlay .tb6-greet{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:15px 18px;margin-bottom:18px;border:1px solid rgba(255,255,255,.1);border-radius:17px;background:radial-gradient(80% 120% at 8% 0%,rgba(250,135,61,.12),transparent 55%),linear-gradient(160deg,rgba(14,24,40,.92),rgba(7,12,22,.95));}
#rp-overlay .tb6-hi{color:#F0F5FC;font-size:18px;font-weight:950;letter-spacing:-.02em;}
