#rp-overlay .tb6-item-main{flex:1;min-width:0;}
#rp-overlay .tb6-item-main strong{display:block;color:#F0F5FC;font-size:12px;font-weight:850;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
#rp-overlay .tb6-item-main span{display:block;color:#8b95a7;font-size:9.6px;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
#rp-overlay .tb6-flame{flex:0 0 auto;padding:4px 10px;border-radius:999px;border:1px solid rgba(251,113,133,.55);background:rgba(251,113,133,.12);color:#FECDD3;font-size:9px;font-weight:950;white-space:nowrap;}
#rp-overlay .tb6-late{flex:0 0 auto;padding:4px 10px;border-radius:999px;border:1px solid rgba(251,191,36,.45);background:rgba(251,191,36,.09);color:#FDE68A;font-size:9px;font-weight:950;white-space:nowrap;}
