#rp-overlay .tb6-empty{color:#77839a;font-size:10.4px;padding:6px 2px 2px;}
#rp-overlay .tb6-wrapline{color:#B9C4D8;font-size:11px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;}
#rp-overlay .tb6-cleared{padding:4px 11px;border-radius:999px;border:1px solid rgba(71,209,108,.4);background:rgba(71,209,108,.09);color:#B8F0CB;font-size:9.4px;font-weight:950;}
/* NOW line */
#rp-overlay .tb6-now{position:relative;display:flex;align-items:center;gap:8px;margin:2px 0 14px;padding-left:46px;}
#rp-overlay .tb6-now-dot{width:10px;height:10px;border-radius:50%;background:#FF5A5A;box-shadow:0 0 12px #FF5A5A;animation:tb6pulse 1.6s ease-in-out infinite;}
#rp-overlay .tb6-now-lbl{color:#FF8A8A;font-size:8.6px;font-weight:950;letter-spacing:1.2px;}
#rp-overlay .tb6-now-line{flex:1;height:1.5px;background:linear-gradient(90deg,rgba(255,90,90,.75),transparent);}
