@media(max-width:760px){
  #rp-overlay .tb6-slot{grid-template-columns:44px minmax(0,1fr);gap:10px;}
  #rp-overlay .tb6-timeline:before{left:50px;}
  #rp-overlay .tb6-item{flex-wrap:wrap;}
  #rp-overlay .tb6-item-acts{width:100%;justify-content:flex-start;}
