  }
  #rp-overlay .cux8-overview .cux8-tile:after{right:clamp(10px,.9vw,14px)!important;bottom:clamp(8px,1.1vh,13px)!important;}

  /* v585/v587: hide the do-nothing scrollbars on the two side columns AND every scroller inside them */
  #rp-overlay .cux8-overview .cux8-brief,
