}
#rp-overlay .ps62-center-body{padding:clamp(14px,1vw,20px)!important;}
#rp-overlay .ps62-center .cl2-center-body{padding:0!important;gap:clamp(14px,1vw,20px)!important;}
#rp-overlay .ps62-dialer>.cl2-body{padding:clamp(14px,1vw,18px)!important;}

/* The workflow buttons belong after the content; they must not cover fields. */
#rp-overlay .ps62-center-footer,
#rp-overlay .cl592-footer{
  position:static!important;
  inset:auto!important;
  width:auto!important;
  margin:0!important;
  padding:clamp(13px,1vw,18px)!important;
  background:#09131D!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

/* Let call-stage guidance and live-assist cards size to their content. */
#rp-overlay .cl592-call-top{align-items:start!important;gap:clamp(14px,1vw,20px)!important;}
#rp-overlay .cl592-ai-card,
#rp-overlay .cl592-live-card,
#rp-overlay .cl592-live-grid article{
