#rp-overlay .ps62-panel-copy{font-size:clamp(10px,.62vw,12px)!important;}

/* The queue tray remains intentionally horizontal; it is the only nested
   scroller on the page and matches the requested left-to-right interaction. */
#rp-overlay .ps90-queue-tray{width:100%!important;}
#rp-overlay .ps90-track{overflow-x:auto!important;overflow-y:hidden!important;}

/* Normal desktop/laptop: keep three columns as long as they genuinely fit. */
@media(max-width:1640px){
  #rp-overlay .ps62-command{
    grid-template-columns:minmax(145px,.34fr) minmax(0,1fr) minmax(270px,.76fr) 64px!important;
    grid-template-areas:
      "label company actions queue"
      "label steps steps queue"!important;
  }
  #rp-overlay .ps62-stepper{max-width:760px!important;justify-self:center!important;}
