  #rp-overlay .ps62-workbench{grid-template-columns:1fr!important;}
  #rp-overlay .ps62-context{grid-column:auto!important;}
  #rp-overlay .ps62-context-body{grid-template-columns:1fr!important;}
  #rp-overlay .cl592-call-top{grid-template-columns:1fr!important;}
  #rp-overlay .cl592-live-card{grid-column:auto!important;}
